 * @param {number[]} salary
 * @return {number}
 */
var average = function(salary) {
    let sum = 0;
    let min = Infinity;
    let max = -Infinity;

    for (const value of salary) {
        sum += value;
        min = Math.min(min, value);
        max = Math.max(max, value);
    }

    return (sum - min - max) / (salary.length - 2);
};
