/**
 * @param {number[][]} grid
 * @param {number[][]} hits
 * @return {number[]}
 */
var hitBricks = function(grid, hits) {
    const m = grid.length;
    const n = grid[0].length;
    const roof = m * n;
    const board = grid.map(row => row.slice());
    const removed = new Uint8Array(hits.length);

    for (let i = 0; i < hits.length; i++) {
        const [r, c] = hits[i];
        if (board[r][c] === 1) {
            removed[i] = 1;
            board[r][c] = 0;
        }
    }

    const parent = new Int32Array(roof + 1);
    const size = new Int32Array(roof + 1);
    for (let i = 0; i <= roof; i++) {
        parent[i] = i;
        size[i] = 1;
    }

    const find = (x) => {
        while (parent[x] !== x) {
            parent[x] = parent[parent[x]];
            x = parent[x];
        }
        return x;
    };

    const union = (a, b) => {
        let rootA = find(a);
        let rootB = find(b);
        if (rootA === rootB) return;

        if (size[rootA] < size[rootB]) {
            [rootA, rootB] = [rootB, rootA];
        }
        parent[rootB] = rootA;
        size[rootA] += size[rootB];
    };

    for (let r = 0; r < m; r++) {
        for (let c = 0; c < n; c++) {
            if (board[r][c] === 0) continue;

            const id = r * n + c;
            if (r === 0) union(id, roof);
            if (r > 0 && board[r - 1][c] === 1) union(id, id - n);
            if (c > 0 && board[r][c - 1] === 1) union(id, id - 1);
        }
    }

    const result = new Array(hits.length).fill(0);
    const directions = [-1, 0, 1, 0, -1];

    for (let i = hits.length - 1; i >= 0; i--) {
        if (removed[i] === 0) continue;

        const [r, c] = hits[i];
        const id = r * n + c;
        const before = size[find(roof)];

        board[r][c] = 1;
        if (r === 0) union(id, roof);

        for (let d = 0; d < 4; d++) {
            const nr = r + directions[d];
            const nc = c + directions[d + 1];

            if (
                nr >= 0 && nr < m &&
                nc >= 0 && nc < n &&
                board[nr][nc] === 1
            ) {
                union(id, nr * n + nc);
            }
        }

        result[i] = Math.max(0, size[find(roof)] - before - 1);
    }

    return result;
};
