/**
 * @param {number[]} arr
 * @return {number}
 */
var numFactoredBinaryTrees = function(arr) {
    const MOD = 1000000007n;
    arr.sort((a, b) => a - b);

    const dp = new Map();
    let total = 0n;

    for (let i = 0; i < arr.length; i++) {
        const value = arr[i];
        let ways = 1n;

        for (let j = 0; j < i; j++) {
            const left = arr[j];
            if (value % left !== 0) continue;

            const rightWays = dp.get(value / left);
            if (rightWays !== undefined) {
                ways = (ways + dp.get(left) * rightWays) % MOD;
            }
        }

        dp.set(value, ways);
        total = (total + ways) % MOD;
    }

    return Number(total);
};
```

