var clumsy = function(n) {
    let total = 0;
    let term = n;
    let operation = 0;

    for (let i = n - 1; i >= 1; i--) {
        switch (operation) {
            case 0:
                term *= i;
                break;
            case 1:
                term = Math.trunc(term / i);
                break;
            case 2:
                total += term;
                term = i;
                break;
            case 3:
                total += term;
                term = -i;
                break;
        }
        operation = (operation + 1) % 4;
    }

    return total + term;
};
