/**
 * @param {number} m
 * @param {number} k
 */
var MKAverage = function(m, k) {
    this.m = m;
    this.k = k;
    this.size = 0;
    this.position = 0;
    this.window = new Int32Array(m);

    this.limit = 100000;
    this.countTree = new Int32Array(this.limit + 1);
    this.sumTree = new Float64Array(this.limit + 1);
};

/**
 * @param {number} num
 * @return {void}
 */
MKAverage.prototype.addElement = function(num) {
    if (this.size === this.m) {
        const oldest = this.window[this.position];

        for (let i = oldest; i <= this.limit; i += i & -i) {
            this.countTree[i]--;
            this.sumTree[i] -= oldest;
        }
    } else {
        this.size++;
    }

    this.window[this.position] = num;
    this.position = (this.position + 1) % this.m;

    for (let i = num; i <= this.limit; i += i & -i) {
        this.countTree[i]++;
        this.sumTree[i] += num;
    }
};

/**
 * @return {number}
 */
MKAverage.prototype.calculateMKAverage = function() {
    if (this.size < this.m) {
        return -1;
    }

    // Find the sum of the smallest rank elements using Fenwick binary lifting.
    const sumSmallest = (rank) => {
        let index = 0;
        let sum = 0;

        for (let step = 65536; step > 0; step >>= 1) {
            const next = index + step;

            if (next <= this.limit && this.countTree[next] < rank) {
                rank -= this.countTree[next];
                sum += this.sumTree[next];
                index = next;
            }
        }

        // Any remaining elements have value index + 1.
        return sum + rank * (index + 1);
    };

    const middleSum = sumSmallest(this.m - this.k) - sumSmallest(this.k);
    return Math.floor(middleSum / (this.m - 2 * this.k));
};

