    const powers = new Int32Array(numSlots);
    let stateCount = 1;

    for (let i = 0; i < numSlots; i++) {
        powers[i] = stateCount;
        stateCount *= 3;
    }

    const memo = new Int32Array(stateCount);
    memo.fill(-1);

