 * @param {number[]} tasks
 * @param {number} sessionTime
 * @return {number}
 */
var minSessions = function(tasks, sessionTime) {
    const n = tasks.length;
    const size = 1 << n;
    const sessions = new Uint8Array(size);
    const usedTime = new Uint8Array(size);

    sessions.fill(n + 1);
    sessions[0] = 1;

    // Minimize session count, then time used in the last session.
    for (let mask = 1; mask < size; mask++) {
        for (let bits = mask; bits !== 0; bits &= bits - 1) {
            const bit = bits & -bits;
            const i = 31 - Math.clz32(bit);
            const previous = mask ^ bit;

            let count = sessions[previous];
            let time = usedTime[previous] + tasks[i];

            if (time > sessionTime) {
                count++;
                time = tasks[i];
            }

            if (
                count < sessions[mask] ||
                (count === sessions[mask] && time < usedTime[mask])
            ) {
                sessions[mask] = count;
                usedTime[mask] = time;
            }
        }
    }

    return sessions[size - 1];
};
