var medianSlidingWindow = function(nums, k) {
    const values = Array.from(new Set(nums)).sort((a, b) => a - b);
    const size = values.length;
    const ranks = new Map();

    for (let i = 0; i < size; i++) {
        ranks.set(values[i], i + 1);
    }

    const tree = new Int32Array(size + 1);

    function update(index, delta) {
        while (index <= size) {
            tree[index] += delta;
            index += index & -index;
        }
    }

    let highestBit = 1;
    while (highestBit * 2 <= size) {
        highestBit *= 2;
    }

    // Return the value with the given 1-based rank in the window.
    function kth(rank) {
        let index = 0;

        for (let step = highestBit; step > 0; step >>= 1) {
            const next = index + step;
            if (next <= size && tree[next] < rank) {
                rank -= tree[next];
                index = next;
            }
        }

        return values[index];
    }

    const result = [];
    const leftRank = Math.floor((k + 1) / 2);
    const rightRank = Math.floor(k / 2) + 1;

    for (let i = 0; i < nums.length; i++) {
        update(ranks.get(nums[i]), 1);

