var regionsBySlashes = function(grid) {
    const n = grid.length;
    const total = 4 * n * n;
    const parent = new Int32Array(total);
    const size = new Int32Array(total);
    let regions = total;

    for (let i = 0; i < total; i++) {
        parent[i] = i;
        size[i] = 1;
    }

    function find(x) {
        while (x !== parent[x]) {
            parent[x] = parent[parent[x]];
            x = parent[x];
        }
        return x;
    }

    function union(a, b) {
        a = find(a);
        b = find(b);
        if (a === b) return;

        if (size[a] < size[b]) {
            [a, b] = [b, a];
        }
        parent[b] = a;
        size[a] += size[b];
        regions--;
    }

    for (let r = 0; r < n; r++) {
        for (let c = 0; c < n; c++) {
            // Each cell has four triangles: top, right, bottom, left.
            const base = 4 * (r * n + c);
            const ch = grid[r][c];

            if (ch !== '\\') {
                union(base, base + 3);
                union(base + 1, base + 2);
            }
            if (ch !== '/') {
                union(base, base + 1);
                union(base + 2, base + 3);
            }

            if (r + 1 < n) {
                union(base + 2, base + 4 * n);
            }
            if (c + 1 < n) {
                union(base + 1, base + 7);
            }
        }
    }

    return regions;
};
